# ============================================================
# CELL 08 — PSEUDO-LABEL QUALITY AUDIT
# ============================================================
#
# Purpose:
#   - Inspect pseudo-labels generated by the completed run.
#   - Evaluate quality using gold VALIDATION links only.
#   - Analyze pseudo-label quality by self-training round.
#   - Save the diagnostic report to Google Drive.
#
# No training.
# No gold Test labels used for correctness assessment.
#
# All variables are local to avoid Marimo redefinition errors.
# ============================================================


def _audit_pseudo_labels_stage4():

    import json
    from pathlib import Path

    import torch

    # ========================================================
    # 1. BASELINE RUN CONFIGURATION
    # ========================================================

    # IMPORTANT:
    # This is the ORIGINAL 300-epoch self-training run.
    # It is NOT the new iterative=False ablation run.

    baseline_run_id = (
        "paper_method_20261023_160901_s66"
    )

    baseline_root = (
        WORK / "runs" / baseline_run_id
    )

    baseline_root.mkdir(
        parents=True,
        exist_ok=True,
    )

    baseline_drive = (
        "paper_method_runs/" + baseline_run_id
    )

    print(
        "[AUDIT] Baseline:",
        baseline_run_id,
        flush=True,
    )

    # ========================================================
    # 2. LOCATE ORIGINAL TRAINING OUTPUT
    # ========================================================

    output_pointer = (
        baseline_root / "out_folder.txt"
    )

    if not output_pointer.is_file():

        fs_drive.get_file(
            baseline_drive + "/out_folder.txt",
            str(output_pointer),
        )

    output_dir = Path(
        output_pointer.read_text(
            encoding="utf-8"
        ).strip()
    )

    # ========================================================
    # 3. LOCATE RESUME CHECKPOINT
    # ========================================================

    snapshot = (
        output_dir / "resume_state.pt"
    )

    # Prefer local checkpoint.
    # Otherwise download from Drive.

    if not snapshot.is_file():

        snapshot = (
            baseline_root / "resume_state_audit.pt"
        )

        if not snapshot.is_file():

            print(
                "[AUDIT] Downloading saved snapshot "
                "from Google Drive (~1.2 GB)...",
                flush=True,
            )

            fs_drive.get_file(
                baseline_drive + "/resume_state.pt",
                str(snapshot),
            )

    assert snapshot.is_file(), (
        "Cannot find resume_state.pt"
    )

    print(
        "[AUDIT] Snapshot:",
        snapshot,
        flush=True,
    )

    # ========================================================
    # 4. LOAD PSEUDO-LABELS FROM CHECKPOINT
    # ========================================================

    # Only load trusted checkpoints from our own run.

    checkpoint = torch.load(
        snapshot,
        map_location="cpu",
        weights_only=False,
        mmap=True,
    )

    assert (
        checkpoint["format"]
        == "CLAMEA_METHOD_V12_STATE"
    )

    assert (
        int(checkpoint["random_seed"])
        == 66
    )

    saved_epoch = int(
        checkpoint["epoch"]
    )

    pseudo_pairs = list(
        zip(
            [
                int(x)
                for x in checkpoint["new_e1"]
            ],
            [
                int(x)
                for x in checkpoint["new_e2"]
            ],
        )
    )

    del checkpoint

    print(
        "[AUDIT] Snapshot epoch:",
        saved_epoch,
        flush=True,
    )

    print(
        "[AUDIT] Total pseudo-pairs:",
        len(pseudo_pairs),
        flush=True,
    )

    # ========================================================
    # 5. REBUILD EXACT CLAMEA ENTITY-ID MAPPING
    # ========================================================

    # Instead of constructing a complete KGs object,
    # use its original mapping methods.
    #
    # This avoids loading gold Test links unnecessarily.

    from kgs import KGs as _KGsReader

    reader = _KGsReader.__new__(
        _KGsReader
    )

    dataset_root = Path(data_dir)

    triples1, entities1, _ = (
        reader.read_relation_triples(
            str(dataset_root / "rel_triples_1")
        )
    )

    triples2, entities2, _ = (
        reader.read_relation_triples(
            str(dataset_root / "rel_triples_2")
        )
    )

    # Same ordered=True mapping as training.

    map_left, map_right, *_ = (
        reader.generate_mapping_id(
            triples1,
            entities1,
            triples2,
            entities2,
            ordered=True,
        )
    )

    del triples1
    del triples2
    del entities1
    del entities2

    print(
        "[AUDIT] Entity-ID mapping rebuilt",
        flush=True,
    )

    # ========================================================
    # 6. LOAD VALIDATION GOLD LINKS ONLY
    # ========================================================

    validation_pairs = (
        reader.read_links(
            str(
                dataset_root / "721valid_links"
            ),
            map_left,
            map_right,
        )
    )

    valid_left_to_right = {
        int(a): int(b)
        for a, b in validation_pairs
    }

    valid_right_to_left = {
        int(b): int(a)
        for a, b in validation_pairs
    }

    assert len(validation_pairs) == 1284

    assert (
        len(valid_left_to_right)
        == len(valid_right_to_left)
        == 1284
    ), (
        "Validation split is not one-to-one. "
        "Audit logic needs adjustment."
    )

    print(
        "[AUDIT] Validation gold pairs:",
        len(validation_pairs),
        flush=True,
    )

    # ========================================================
    # 7. PSEUDO-LABEL QUALITY FUNCTION
    # ========================================================

    def measure(pairs):

        # A pseudo-pair is verifiable if at least
        # one of its entities belongs to Validation.

        checked = [
            (a, b)
            for a, b in pairs
            if (
                a in valid_left_to_right
                or b in valid_right_to_left
            )
        ]

        correct = sum(
            valid_left_to_right.get(a) == b
            for a, b in checked
        )

        incorrect = (
            len(checked) - correct
        )

        precision = (
            round(
                correct / len(checked),
                6,
            )
            if checked
            else None
        )

        return {
            "pseudo_pairs": len(pairs),

            "validation_verifiable": (
                len(checked)
            ),

            "validation_correct": correct,

            "validation_incorrect": incorrect,

            "validation_subset_precision": (
                precision
            ),

            "not_verifiable_from_validation": (
                len(pairs) - len(checked)
            ),
        }

    # ========================================================
    # 8. SPLIT PSEUDO-PAIRS BY SELF-TRAINING ROUND
    # ========================================================

    # Counts extracted from the completed baseline log.

    waves = [
        (70, 3424),
        (140, 2716),
        (210, 1730),
        (280, 1017),
    ]

    expected_count = sum(
        size
        for epoch, size in waves
        if saved_epoch >= epoch
    )

    assert (
        len(pseudo_pairs) == expected_count
    ), (
        f"Snapshot contains {len(pseudo_pairs)} "
        f"pseudo-pairs, but log predicts "
        f"{expected_count} through epoch "
        f"{saved_epoch}. "
        "Verify snapshot and run ID."
    )

    by_wave = []

    position = 0

    for epoch, size in waves:

        if epoch > saved_epoch:
            break

        subset = pseudo_pairs[
            position:position + size
        ]

        position += size

        wave_result = {
            "generated_at_epoch": epoch,
            **measure(subset),
        }

        by_wave.append(
            wave_result
        )

    # ========================================================
    # 9. OVERALL EVALUATION
    # ========================================================

    overall = measure(
        pseudo_pairs
    )

    report = {
        "run_id": baseline_run_id,

        "snapshot_epoch": saved_epoch,

        "scope": "VALIDATION_GOLD_ONLY",

        "overall": overall,

        "by_wave": by_wave,

        "interpretation_limit": (
            "Precision is calculated only for "
            "pseudo-pairs touching known Validation "
            "entities. It does not measure "
            "full pseudo-label precision."
        ),
    }

    print()
    print(
        "=" * 55,
        flush=True,
    )

    print(
        "PSEUDO-LABEL QUALITY AUDIT",
        flush=True,
    )

    print(
        "=" * 55,
        flush=True,
    )

    print(
        json.dumps(
            report,
            ensure_ascii=False,
            indent=2,
        ),
        flush=True,
    )

    # ========================================================
    # 10. SAVE REPORT LOCALLY
    # ========================================================

    destination = (
        baseline_root
        / "pseudo_quality_validation_only.json"
    )

    destination.write_text(
        json.dumps(
            report,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    # ========================================================
    # 11. BACKUP REPORT TO GOOGLE DRIVE
    # ========================================================

    remote_diagnostics = (
        baseline_drive + "/diagnostics"
    )

    fs_drive.makedirs(
        remote_diagnostics,
        exist_ok=True,
    )

    fs_drive.put_file(
        str(destination),
        remote_diagnostics
        + "/"
        + destination.name,
    )

    print()
    print(
        "[DRIVE] Audit report backed up:",
        remote_diagnostics
        + "/"
        + destination.name,
        flush=True,
    )

    print(
        "[AUDIT] COMPLETE",
        flush=True,
    )

    return report


# ============================================================
# 12. EXECUTE AUDIT
# ============================================================

_audit_pseudo_labels_stage4()
